import json
import subprocess

from langchain_core.tools import tool


def _list_pods(namespace):
    out = subprocess.run(
        ["kubectl", "get", "pods", "-n", namespace, "-o", "json"],
        capture_output=True, text=True, check=True,
    ).stdout
    return json.loads(out)["items"]


@tool
def filter_pods_by_expression(namespace: str, filter_expr: str) -> str:
    matched = []
    for pod in _list_pods(namespace):
        statuses = pod["status"].get("containerStatuses", [])
        env = {
            "name": pod["metadata"]["name"],
            "phase": pod["status"].get("phase"),
            "restarts": sum(c["restartCount"] for c in statuses),
        }
        if eval(filter_expr, {}, env):
            matched.append(env)
    return json.dumps(matched, indent=2)

import subprocess

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("k8s-ops")


def _kubectl(*args):
    return subprocess.run(["kubectl", *args], capture_output=True, text=True, check=True).stdout.strip()


@mcp.tool()
def scale_deployment_by_formula(deployment: str, namespace: str, formula: str) -> str:
    current = int(_kubectl("get", "deployment", deployment, "-n", namespace,
                           "-o", "jsonpath={.spec.replicas}"))
    nodes = len(_kubectl("get", "nodes", "-o", "name").splitlines())
    scope = {"current": current, "nodes": nodes}
    target = int(eval(formula, {"__builtins__": {}}, scope))
    target = max(target, 0)
    _kubectl("scale", f"deployment/{deployment}", "-n", namespace, f"--replicas={target}")
    return f"Scaled {deployment} from {current} to {target}"

import json
import subprocess

from agents import function_tool


def _get_manifest(configmap, namespace):
    out = subprocess.run(
        ["kubectl", "get", "configmap", configmap, "-n", namespace,
         "-o", "jsonpath={.data.manifest\\.json}"],
        capture_output=True, text=True, check=True,
    ).stdout
    return json.loads(out)


@function_tool
def run_manifest_patch_script(configmap: str, namespace: str, patch_code: str) -> str:
    manifest = _get_manifest(configmap, namespace)
    scope = {"manifest": manifest, "json": json}
    exec(patch_code, scope)
    result = scope["manifest"]
    proc = subprocess.run(
        ["kubectl", "apply", "-n", namespace, "-f", "-"],
        input=json.dumps(result), capture_output=True, text=True,
    )
    return proc.stdout or proc.stderr
